    if (tools && container.contains(tools)) document.body.appendChild(tools);   // keep it safe while the pond is rebuilt
    container.innerHTML = "";
    const E = entries.length;
    const phone = window.innerWidth <= 700;
    // plenty of ducks: every entry gets one, plus lots of plain ones
    const N = Math.min(100, Math.max(E, phone ? Math.max(16, E + 8) : Math.max(20, Math.min(64, E + 12))));
    const rr = Math.max(24, Math.min(56, R * Math.sqrt(0.3 / N))) * (phone ? 1.18 : 1);

    const svg = el("svg", { viewBox: "385 125 1150 905", class: "pond-svg", role: "group", "aria-label": "a pool of rubber ducks" });
    svg.innerHTML = "<defs>" + DEFS + "</defs>" + '<g id="pd-scene">' + POOL + '<g clip-path="url(#pd-clip)"><g class="pd-rings"></g><g class="pd-ducks"></g></g></g>';
    const rings = svg.querySelector(".pd-rings"), layer = svg.querySelector(".pd-ducks");
    const hint = document.createElement("p");
    hint.className = "pond-hint";
    hint.append("the ducks hold my thoughts.", Object.assign(document.createElement("br"), { className: "pond-br" }), " look around to find them.");   // the line break only shows on phones
    hint.hidden = !E;
    const title = document.createElement("h1"); title.className = "pond-title"; title.textContent = "the duck pond";
    container.append(title, hint); if (tools) container.appendChild(tools); container.appendChild(svg);
    // a magnifying box: drag it round the pool to see the ducks close up (it just re-draws the live pool, zoomed)
